using A = std::remove_cvref_t<const long&>;
// Шаг 1: убрать & — const long. Шаг 2: убрать const — long.
using B = std::remove_cvref_t<int* const>;
// Ссылки нет. Убирается const самого указателя: B — int*.
// Это не даёт права менять объект, объявленный const, через другой путь доступа.
